// Extract content from file
const body = $input.first().json.body;
const fileName = body.fileName;
const filePath = body.filePath;
const fileContent = $binary.data.data.toString('utf8');

// Derive metadata from filename
const baseName = fileName.replace(/\.(md|pdf|docx)$/i, '');
const parts = baseName.split('_');

// Extract title (convert underscores to spaces, capitalize)
const title = parts
  .map(word => word.charAt(0).toUpperCase() + word.slice(1))
  .join(' ');

// Determine category from filename patterns
let category = 'general';
if (baseName.includes('legal')) category = 'legal';
else if (baseName.includes('client')) category = 'client-service';
else if (baseName.includes('process')) category = 'processes';
else if (baseName.includes('fee') || baseName.includes('billing')) category = 'billing';
else if (baseName.includes('faq')) category = 'faq';
else if (baseName.includes('glossary') || baseName.includes('terminology')) category = 'reference';

// Determine content type
let contentType = 'general';
if (baseName.includes('guide')) contentType = 'guide';
else if (baseName.includes('faq')) contentType = 'faq';
else if (baseName.includes('glossary')) contentType = 'glossary';
else if (baseName.includes('process')) contentType = 'process';
else if (baseName.includes('scenario')) contentType = 'scenario';

// Extract tags from filename
const tags = parts.filter(part => 
  !['the', 'and', 'or', 'of', 'in', 'to', 'a', 'an'].includes(part.toLowerCase())
);

return {
  json: {
    title: title,
    content: fileContent,
    content_type: contentType,
    category: category,
    tenant_id: 'default',
    source: filePath,
    tags: tags,
    file_name: fileName
  }
};

// Split content into chunks if it's too long (>1000 chars)
const data = $json;
const maxChunkSize = 1000;
const chunks = [];

if (data.content.length <= maxChunkSize) {
  chunks.push({
    title: data.title,
    content: data.content,
    content_type: data.content_type,
    category: data.category,
    tenant_id: data.tenant_id,
    source: data.source,
    tags: JSON.stringify(data.tags),
    chunk_index: 0,
    total_chunks: 1
  });
} else {
  // Split into chunks by sentences
  const sentences = data.content.split(/[.!?]+/);
  let currentChunk = '';
  let chunkIndex = 0;

  sentences.forEach((sentence) => {
    if (currentChunk.length + sentence.length > maxChunkSize && currentChunk.length > 0) {
      chunks.push({
        title: `${data.title} (Part ${chunkIndex + 1})`,
        content: currentChunk.trim(),
        content_type: data.content_type,
        category: data.category,
        tenant_id: data.tenant_id,
        source: data.source,
        tags: JSON.stringify(data.tags),
        chunk_index: chunkIndex,
        total_chunks: 0
      });
      currentChunk = sentence;
      chunkIndex++;
    } else {
      currentChunk += sentence + '.';
    }
  });

  // Add the last chunk
  if (currentChunk.trim()) {
    chunks.push({
      title: `${data.title} (Part ${chunkIndex + 1})`,
      content: currentChunk.trim(),
      content_type: data.content_type,
      category: data.category,
      tenant_id: data.tenant_id,
      source: data.source,
      tags: JSON.stringify(data.tags),
      chunk_index: chunkIndex,
      total_chunks: 0
    });
  }

  // Update total_chunks
  chunks.forEach(chunk => {
    chunk.total_chunks = chunks.length;
  });
}

return chunks.map(chunk => ({ json: chunk }));

// Format data for database insertion
const chunk = $input.first().json;
const embedding = $('Generate Embeddings').first().json.embedding;

// Format embedding as PostgreSQL vector
const vectorString = `[${embedding.join(',')}]`;

return {
  json: {
    tenant_id: chunk.tenant_id,
    title: chunk.title,
    content: chunk.content,
    content_type: chunk.content_type,
    embedding: vectorString,
    source: chunk.source,
    category: chunk.category,
    tags: chunk.tags,
    is_active: true,
    version: 1,
    access_count: 0
  }
};
